t.script:
/* Clinic slot picker: doctor + date -> free time buttons.
 * Writes the chosen local time ('YYYY-MM-DDTHH:MM') into a hidden "appointment_date" input. */
(function () {
    'use strict';

    function rpc(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params}),
        }).then(function (r) { return r.json(); }).then(function (d) { return d.result; });
    }

    window.ClinicSlotPicker = function (o) {
        var form = o.form, dateEl = o.dateInput, box = o.slotsBox;
        var hidden = o.hidden, timeEl = o.timeInput;
        var onChange = o.onChange || function () {};
        var seq = 0;

        function setValue(v) {
            hidden.value = v || '';
            onChange(hidden.value);
        }

        function doctorId() {
            var el = form.querySelector('input[name="doctor_id"]:checked') ||
                     form.querySelector('select[name="doctor_id"]');
            return el && el.value ? el.value : '';
        }

        function hint(text, cls) {
            box.innerHTML = '';
            var d = document.createElement('div');
            d.className = 'small ' + (cls || 'text-muted');
            d.textContent = text;
            box.appendChild(d);
        }

        function render(res) {
            timeEl.classList.add('d-none');
            if (!res) { return hint('Could not load available times. Please try again.', 'text-danger'); }

            if (!res.has_schedule) {
                // Doctor has no weekly schedule: let the patient pick any time
                hint('Pick your preferred time:');
                timeEl.classList.remove('d-none');
                return;
            }
            if (!res.slots.length) {
                return hint('No free slots on this date. Please choose another date.', 'text-danger');
            }
            box.innerHTML = '';
            res.slots.forEach(function (s) {
                var b = document.createElement('button');
                b.type = 'button';
                b.className = 'btn btn-outline-primary btn-sm m-1 cl-slot';
                b.textContent = s.label;
                b.addEventListener('click', function () {
                    box.querySelectorAll('.cl-slot').forEach(function (x) {
                        x.classList.remove('btn-primary');
                        x.classList.add('btn-outline-primary');
                    });
                    b.classList.remove('btn-outline-primary');
                    b.classList.add('btn-primary');
                    setValue(s.value);
                });
                box.appendChild(b);
            });
        }

        function refresh() {
            setValue('');
            timeEl.value = '';
            timeEl.classList.add('d-none');
            var doc = doctorId(), day = dateEl.value;
            if (!doc || !day) {
                return hint('Select a doctor and a date to see available times.');
            }
            hint('Loading available times...');
            var token = ++seq;
            rpc('/clinic/slots', {doctor_id: doc, date: day}).then(function (res) {
                if (token === seq) { render(res); }
            }).catch(function () {
                if (token === seq) { render(null); }
            });
        }

        form.addEventListener('change', function (e) {
            if (e.target === dateEl || e.target.name === 'doctor_id') { refresh(); }
        });
        timeEl.addEventListener('change', function () {
            setValue(timeEl.value && dateEl.value ? dateEl.value + 'T' + timeEl.value : '');
        });

        // Capture phase: runs before the page's own submit handlers (loading spinner etc.)
        form.addEventListener('submit', function (e) {
            if (!hidden.value) {
                e.preventDefault();
                e.stopImmediatePropagation();
                var warn = box.querySelector('.cl-slot-warn');
                if (!warn) {
                    warn = document.createElement('div');
                    warn.className = 'cl-slot-warn text-danger small mt-2';
                    warn.textContent = 'Please select a time slot.';
                    box.appendChild(warn);
                }
            }
        }, true);

        refresh();
    };
})();

(function () {
    'use strict';
    var root = document.getElementById('lgRoot');
    if (!root) { return; }
    root.classList.add('js');

    function $(s, c) { return (c || document).querySelector(s); }
    function $$(s, c) { return [].slice.call((c || document).querySelectorAll(s)); }
    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* ---- which element scrolls? (Odoo often scrolls #wrapwrap, not window) ---- */
    var wrap = document.getElementById('wrapwrap');
    var scroller = window;
    if (wrap) {
        var oy = getComputedStyle(wrap).overflowY;
        if ((oy === 'auto' || oy === 'scroll') && wrap.scrollHeight > wrap.clientHeight + 5) { scroller = wrap; }
    }
    function st() { return scroller === window ? (window.pageYOffset || document.documentElement.scrollTop) : scroller.scrollTop; }
    function sh() { return scroller === window ? document.documentElement.scrollHeight : scroller.scrollHeight; }
    function vh() { return window.innerHeight; }

    /* ---- reveal on scroll + count-up ---- */
    function countUp(el) {
        var to = parseFloat(el.getAttribute('data-count')) || 0, t0 = performance.now(), d = 1500;
        (function f(n) {
            var p = Math.min((n - t0) / d, 1), e = 1 - Math.pow(1 - p, 3);
            el.textContent = Math.round(to * e);
            if (p < 1) { requestAnimationFrame(f); }
        })(t0);
    }
    var io = null;
    if ('IntersectionObserver' in window) {
        io = new IntersectionObserver(function (entries) {
            entries.forEach(function (e) {
                if (e.isIntersecting) {
                    e.target.classList.add('in');
                    if (e.target.hasAttribute('data-count')) { countUp(e.target); }
                    io.unobserve(e.target);
                }
            });
        }, {threshold: 0.15, rootMargin: '0px 0px -6% 0px'});
    }
    $$('.rv, .lg-step, [data-count]').forEach(function (el) {
        if (io) { io.observe(el); } else { el.classList.add('in'); if (el.hasAttribute('data-count')) { countUp(el); } }
    });
    setTimeout(function () {   // safety net if the observer never fired
        if (!$('.rv.in')) { $$('.rv, .lg-step').forEach(function (el) { el.classList.add('in'); }); }
    }, 2500);

    /* ---- glass spotlight + 3D tilt ---- */
    root.addEventListener('pointermove', function (e) {
        var g = e.target.closest ? e.target.closest('.glass') : null;
        if (g) {
            var r = g.getBoundingClientRect();
            g.style.setProperty('--mx', (e.clientX - r.left) + 'px');
            g.style.setProperty('--my', (e.clientY - r.top) + 'px');
        }
    }, {passive: true});
    $$('.tilt').forEach(function (el) {
        el.addEventListener('pointermove', function (e) {
            if (reduce) { return; }
            var r = el.getBoundingClientRect();
            el.style.setProperty('--ry', (((e.clientX - r.left) / r.width - 0.5) * 14) + 'deg');
            el.style.setProperty('--rx', (((e.clientY - r.top) / r.height - 0.5) * -14) + 'deg');
        });
        el.addEventListener('pointerleave', function () {
            el.style.setProperty('--rx', '0deg');
            el.style.setProperty('--ry', '0deg');
        });
    });

    /* ---- magnetic buttons ---- */
    $$('.lg-magnetic').forEach(function (el) {
        el.addEventListener('pointermove', function (e) {
            if (reduce) { return; }
            var r = el.getBoundingClientRect();
            el.style.translate = ((e.clientX - r.left - r.width / 2) * 0.22) + 'px ' + ((e.clientY - r.top - r.height / 2) * 0.32) + 'px';
        });
        el.addEventListener('pointerleave', function () { el.style.translate = '0px 0px'; });
    });

    /* ---- liquid cursor blob in the hero ---- */
    var hero = $('#home'), blob = $('#lgCursor');
    if (hero && blob && !reduce) {
        var tx = hero.clientWidth * 0.3, ty = hero.clientHeight * 0.5, cx = tx, cy = ty;
        hero.addEventListener('pointermove', function (e) {
            var r = hero.getBoundingClientRect();
            tx = e.clientX - r.left; ty = e.clientY - r.top;
        });
        (function loop() {
            cx += (tx - cx) * 0.1; cy += (ty - cy) * 0.1;
            blob.style.transform = 'translate(' + (cx - 85) + 'px,' + (cy - 85) + 'px)';
            requestAnimationFrame(loop);
        })();
    }

    /* ---- nav lens (sliding glass selector) ---- */
    var linkBox = $('#lgLinks'), lens = $('#lgLens'), links = $$('#lgLinks a'), activeLink = links[0];
    function moveLens(a) {
        if (!a || !lens) { return; }
        lens.style.width = a.offsetWidth + 'px';
        lens.style.transform = 'translateX(' + a.offsetLeft + 'px)';
    }
    links.forEach(function (a) { a.addEventListener('mouseenter', function () { moveLens(a); }); });
    if (linkBox) { linkBox.addEventListener('mouseleave', function () { moveLens(activeLink); }); }
    window.addEventListener('resize', function () { moveLens(activeLink); });
    setTimeout(function () { moveLens(activeLink); }, 350);

    /* ---- scroll engine ---- */
    var floatPill = $('#lgFloat'), spyIds = links.map(function (a) { return a.getAttribute('href').slice(1); });
    var ticking = false;
    function update() {
        ticking = false;
        var t = st(), max = sh() - vh();
        root.style.setProperty('--p', max > 0 ? Math.min(t / max, 1) : 0);

        if (!reduce && t < 1600) {
            $$('[data-speed]').forEach(function (el) {
                el.style.setProperty('--py', (t * parseFloat(el.getAttribute('data-speed'))) + 'px');
            });
        }

        var book = $('#book'), inBook = false;
        if (book) { var br = book.getBoundingClientRect(); inBook = br.top < vh() * 0.7 && br.bottom > 0; }
        if (floatPill) { floatPill.classList.toggle('show', t > vh() * 0.7 && !inBook); }

        var tl = $('#howTl');
        if (tl) {
            var r = tl.getBoundingClientRect();
            tl.style.setProperty('--hp', Math.max(0, Math.min(1, (vh() * 0.65 - r.top) / r.height)));
        }

        var current = spyIds[0];
        spyIds.forEach(function (id) {
            var s = document.getElementById(id);
            if (s && s.getBoundingClientRect().top < vh() * 0.4) { current = id; }
        });
        var next = links.filter(function (a) { return a.getAttribute('href') === '#' + current; })[0];
        if (next && next !== activeLink) { activeLink = next; moveLens(activeLink); }
    }
    function onScroll() { if (!ticking) { ticking = true; requestAnimationFrame(update); } }
    scroller.addEventListener('scroll', onScroll, {passive: true});
    window.addEventListener('resize', onScroll);
    update();

    /* ---- smooth anchors ---- */
    $$('a[href^="#"]').forEach(function (a) {
        a.addEventListener('click', function (e) {
            var id = a.getAttribute('href').slice(1), el = id ? document.getElementById(id) : null;
            if (el) { e.preventDefault(); el.scrollIntoView({behavior: reduce ? 'auto' : 'smooth', block: 'start'}); }
        });
    });

    /* ---- doctor carousel ---- */
    var rail = $('#lgRail');
    $$('[data-rail]').forEach(function (b) {
        b.addEventListener('click', function () {
            if (rail) { rail.scrollBy({left: parseInt(b.getAttribute('data-rail'), 10) * 320, behavior: 'smooth'}); }
        });
    });

    /* ---- pick a doctor -> jump to the form ---- */
    $$('[data-doctor]').forEach(function (b) {
        b.addEventListener('click', function () {
            var sel = $('#floatDoctor');
            if (sel) {
                sel.value = b.getAttribute('data-doctor');
                sel.dispatchEvent(new Event('change', {bubbles: true}));
            }
            var book = $('#book');
            if (book) { book.scrollIntoView({behavior: reduce ? 'auto' : 'smooth', block: 'start'}); }
            setTimeout(function () { var d = $('#floatDate'); if (d) { d.focus({preventScroll: true}); } }, 700);
        });
    });

    /* ---- FAQ ---- */
    $$('.lg-fq button').forEach(function (b) {
        b.addEventListener('click', function () {
            var item = b.parentNode, open = item.classList.contains('open');
            $$('.lg-fq').forEach(function (i) { i.classList.remove('open'); });
            if (!open) { item.classList.add('open'); }
        });
    });

    /* ---- booking form ---- */
    var form = $('#apForm');
    if (form) {
        var dateInput = $('#floatDate'), now = new Date();
        dateInput.min = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 10);

        var s1 = $('#apStep1'), s2 = $('#apStep2'), s3 = $('#apStep3');
        var filled = function (id) {
            var el = document.getElementById(id);
            return !!(el && el.value && el.checkValidity());
        };
        var updateProgress = function () {
            s1.classList.toggle('done', filled('floatName') && filled('floatEmail') && filled('floatPhone'));
            s2.classList.toggle('done', filled('floatDoctor'));
            s3.classList.toggle('done', filled('floatSlot'));
        };
        form.addEventListener('input', updateProgress);
        form.addEventListener('change', updateProgress);
        updateProgress();

        if (window.ClinicSlotPicker) {
            window.ClinicSlotPicker({
                form: form, dateInput: dateInput, slotsBox: $('#apSlots'),
                hidden: $('#floatSlot'), timeInput: $('#apTime'), onChange: updateProgress
            });
        }

        form.addEventListener('submit', function () {
            if (form.checkValidity()) {
                $('#apSubmit').classList.add('is-loading');
                $('#apSubmitText').textContent = 'Booking...';
                $('#apSubmitIcon').className = 'fa fa-circle-o-notch';
            }
        });
    }

    if ($('[data-flash]')) {
        setTimeout(function () { var b = $('#book'); if (b) { b.scrollIntoView({behavior: 'smooth', block: 'start'}); } }, 500);
    }
    var y = $('#lgYear');
    if (y) { y.textContent = new Date().getFullYear(); }
})();
